<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';admin_required();
$catalog=admin_permission_catalog();$errors=[];$id=max(0,scalar_int($_GET['edit']??$_POST['id']??0));
if(is_post()){
    verify_csrf();$action=scalar_string($_POST['action']??'save');
    try{
        if($action==='delete'){$roleId=max(0,scalar_int($_POST['id']??0));$used=db()->prepare('SELECT COUNT(*) FROM admins WHERE role_id=?');$used->execute([$roleId]);if((int)$used->fetchColumn()>0)throw new RuntimeException('این نقش به مدیر متصل است و قابل حذف نیست.');db()->prepare('DELETE FROM admin_roles WHERE id=?')->execute([$roleId]);admin_audit_event('role_deleted','role',$roleId);flash('success','نقش حذف شد.');redirect(app_url('admin/roles.php'));}
        $name=trim(scalar_string($_POST['name']??''));$description=trim(scalar_string($_POST['description']??''));$active=isset($_POST['is_active'])?1:0;$permissions=array_values(array_intersect(array_map('strval',(array)($_POST['permissions']??[])),array_keys($catalog)));if(!in_array('view_dashboard',$permissions,true))$permissions[]='view_dashboard';
        if(text_length($name)<2||text_length($name)>100)throw new RuntimeException('نام نقش باید بین ۲ تا ۱۰۰ کاراکتر باشد.');if(text_length($description)>500)throw new RuntimeException('توضیحات نقش بیش از حد طولانی است.');if(!$permissions)throw new RuntimeException('حداقل یک دسترسی برای نقش انتخاب کنید.');
        $pdo=db();$pdo->beginTransaction();
        if($id>0){$stmt=$pdo->prepare('UPDATE admin_roles SET name=?,description=?,is_active=? WHERE id=?');$stmt->execute([$name,$description?:null,$active,$id]);if($stmt->rowCount()===0){$check=$pdo->prepare('SELECT id FROM admin_roles WHERE id=?');$check->execute([$id]);if(!$check->fetchColumn())throw new RuntimeException('نقش پیدا نشد.');}}
        else{$pdo->prepare('INSERT INTO admin_roles(name,description,is_active) VALUES(?,?,?)')->execute([$name,$description?:null,$active]);$id=(int)$pdo->lastInsertId();}
        $pdo->prepare('DELETE FROM admin_role_permissions WHERE role_id=?')->execute([$id]);$insert=$pdo->prepare('INSERT INTO admin_role_permissions(role_id,permission_key) VALUES(?,?)');foreach($permissions as $permission)$insert->execute([$id,$permission]);$pdo->commit();admin_audit_event('role_saved','role',$id,['permissions'=>$permissions]);flash('success','نقش و دسترسی‌ها ذخیره شد.');redirect(app_url('admin/roles.php?edit='.$id));
    }catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof PDOException?'نام نقش تکراری است.':$e->getMessage();}
}
$edit=null;$selected=[];if($id>0){$stmt=db()->prepare('SELECT * FROM admin_roles WHERE id=?');$stmt->execute([$id]);$edit=$stmt->fetch()?:null;if($edit){$p=db()->prepare('SELECT permission_key FROM admin_role_permissions WHERE role_id=?');$p->execute([$id]);$selected=array_map('strval',$p->fetchAll(PDO::FETCH_COLUMN));}}
$roles=db()->query('SELECT r.*,(SELECT COUNT(*) FROM admins a WHERE a.role_id=r.id) admin_count,(SELECT COUNT(*) FROM admin_role_permissions rp WHERE rp.role_id=r.id) permission_count FROM admin_roles r ORDER BY r.name')->fetchAll();$adminPage='admins';$adminTitle='نقش‌ها و سطح دسترسی';require __DIR__.'/partials/header.php';
?>
<div class="admin-title"><div><h1>نقش‌ها و سطح دسترسی</h1><p class="muted">مدیر بدون نقش، مدیر کل محسوب می‌شود.</p></div><a class="btn btn-secondary" href="<?=e(app_url('admin/admin-users.php'))?>">مدیران</a></div>
<?php foreach($errors as $error):?><div class="flash error"><?=e($error)?></div><?php endforeach?>
<form method="post" class="card"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><h2><?=$edit?'ویرایش نقش':'نقش جدید'?></h2><div class="form-grid"><div class="field"><label>نام نقش</label><input name="name" maxlength="100" value="<?=e($edit['name']??'')?>" required></div><div class="field"><label><input type="checkbox" name="is_active" value="1" <?=!isset($edit['is_active'])||$edit['is_active']?'checked':''?>> فعال</label></div><div class="field full"><label>توضیحات</label><input name="description" maxlength="500" value="<?=e($edit['description']??'')?>"></div><div class="field full"><label>دسترسی‌ها</label><div class="permission-grid"><?php foreach($catalog as $key=>$label):?><label><input type="checkbox" name="permissions[]" value="<?=e($key)?>" <?=in_array($key,$selected,true)?'checked':''?>> <?=e($label)?></label><?php endforeach?></div></div></div><button class="btn btn-primary">ذخیره نقش</button><?php if($edit):?><a class="btn btn-secondary" href="<?=e(app_url('admin/roles.php'))?>">نقش جدید</a><?php endif?></form>
<div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>نقش</th><th>دسترسی</th><th>مدیر</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($roles as $role):?><tr><td><strong><?=e($role['name'])?></strong><br><small><?=e($role['description']?:'—')?></small></td><td><?=fa_number($role['permission_count'])?></td><td><?=fa_number($role['admin_count'])?></td><td><?=$role['is_active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-secondary btn-sm" href="<?=e(app_url('admin/roles.php?edit='.(int)$role['id']))?>">ویرایش</a><?php if((int)$role['admin_count']===0):?><form method="post" style="display:inline" data-confirm="این نقش حذف شود؟"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$role['id']?>"><button class="btn btn-danger btn-sm">حذف</button></form><?php endif?></td></tr><?php endforeach?><?php if(!$roles):?><tr><td colspan="5">هنوز نقشی ساخته نشده است.</td></tr><?php endif?></tbody></table></div>
<?php require __DIR__.'/partials/footer.php';
